import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.Crpw6aS5.js";const f=JSON.parse('{"title":"罗恩·弗格森 (Ron Ferguson)","description":"","frontmatter":{},"headers":[],"relativePath":"04_people/ron_ferguson.md","filePath":"04_people/ron_ferguson.md"}'),h={name:"04_people/ron_ferguson.md"};function d(i,a,o,n,s,u){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="罗恩·弗格森-ron-ferguson" tabindex="-1">罗恩·弗格森 (Ron Ferguson) <a class="header-anchor" href="#罗恩·弗格森-ron-ferguson" aria-label="Permalink to &quot;罗恩·弗格森 (Ron Ferguson)&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>全名</td><td>Ronald Eugene Ferguson</td></tr><tr><td>出生</td><td>1941年</td></tr><tr><td>世于</td><td>2023年</td></tr><tr><td>职业</td><td>企业家、保险经理人</td></tr><tr><td>公司</td><td><a href="/search.html?q=通用再保险">通用再保险</a></td></tr></tbody></table><h2 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h2><h3 id="通用再保险-general-re-ceo" tabindex="-1">通用再保险（General Re）CEO <a class="header-anchor" href="#通用再保险-general-re-ceo" aria-label="Permalink to &quot;通用再保险（General Re）CEO&quot;">​</a></h3><ul><li>长期担任<a href="/search.html?q=通用再保险">通用再保险</a>（General Re）CEO</li><li><a href="/search.html?q=通用再保险">通用再保险</a>是全球最大的再保险公司之一</li><li>在弗格森的领导下，公司积累了大量的浮存金</li></ul><h2 id="_1998年-伯克市尔收购" tabindex="-1">1998年：伯克市尔收购 <a class="header-anchor" href="#_1998年-伯克市尔收购" aria-label="Permalink to &quot;1998年：伯克市尔收购&quot;">​</a></h2><h3 id="收购背景" tabindex="-1">收购背景 <a class="header-anchor" href="#收购背景" aria-label="Permalink to &quot;收购背景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>收购年份</td><td>1998年</td></tr><tr><td>收购价格</td><td>约220亿美元</td></tr><tr><td>收购方式</td><td>换股</td></tr><tr><td>收购对象</td><td><a href="/search.html?q=通用再保险">通用再保险</a></td></tr></tbody></table><h3 id="收购动机" tabindex="-1">收购动机 <a class="header-anchor" href="#收购动机" aria-label="Permalink to &quot;收购动机&quot;">​</a></h3><ul><li><a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>看中了<a href="/search.html?q=通用再保险">通用再保险</a>的巨大浮存金</li><li>浮存金是保险业务的核心优势之一</li><li><a href="/search.html?q=伯克尔希哈佩威">伯克尔希哈佩威</a>希望接此扩大保险帝国</li></ul><h2 id="收购后的整合问题" tabindex="-1">收购后的整合问题 <a class="header-anchor" href="#收购后的整合问题" aria-label="Permalink to &quot;收购后的整合问题&quot;">​</a></h2><h3 id="浮存金质量问题" tabindex="-1">浮存金质量问题 <a class="header-anchor" href="#浮存金质量问题" aria-label="Permalink to &quot;浮存金质量问题&quot;">​</a></h3><ul><li>收购后发现部分浮存金质量不如预期</li><li>部分长期保单的缴费赔付超出预计</li></ul><h3 id="再保险合同定价错误" tabindex="-1">再保险合同定价错误 <a class="header-anchor" href="#再保险合同定价错误" aria-label="Permalink to &quot;再保险合同定价错误&quot;">​</a></h3><ul><li>部分再保险合同定价过低</li><li>经济环境变化导致些类保单亏损</li><li>需要长期调整和解决</li></ul><h2 id="巴菲特对弗格森森的评价变化" tabindex="-1">巴菲特对弗格森森的评价变化 <a class="header-anchor" href="#巴菲特对弗格森森的评价变化" aria-label="Permalink to &quot;巴菲特对弗格森森的评价变化&quot;">​</a></h2><h3 id="收购初期" tabindex="-1">收购初期 <a class="header-anchor" href="#收购初期" aria-label="Permalink to &quot;收购初期&quot;">​</a></h3><ul><li>收购时巴菲特对弗格森森的经营管理能力评价较高</li><li>希望通过收购获取优质浮存金</li></ul><h3 id="后来的豌论" tabindex="-1">后来的豌论 <a class="header-anchor" href="#后来的豌论" aria-label="Permalink to &quot;后来的豌论&quot;">​</a></h3><ul><li>随着问题浮现，巴菲特对弗格森森的评价发生了变化</li><li>巴菲特在股东信中表达了部分弹压</li><li>接近退休后，弗格森森离开了<a href="/search.html?q=伯克尔希哈佩威">伯克尔希哈佩威</a></li></ul><h2 id="与阿吉特·贾恩的对比" tabindex="-1">与阿吉特·贾恩的对比 <a class="header-anchor" href="#与阿吉特·贾恩的对比" aria-label="Permalink to &quot;与阿吉特·贾恩的对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>罗恩·弗格森</th><th><a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a></th></tr></thead><tbody><tr><td>职位</td><td><a href="/search.html?q=通用再保险">通用再保险</a> CEO</td><td><a href="/search.html?q=伯克尔希哈佩威">伯克尔希哈佩威</a>保险业务负责人</td></tr><tr><td>主营业务</td><td>再保险</td><td>保险（主要是人字再保险）</td></tr><tr><td>资产管理</td><td>重浮存金规模</td><td>重碑资产管理</td></tr><tr><td>评价</td><td>有争议</td><td>极高</td></tr><tr><td>影响力</td><td>收购年计划重要</td><td>被称为“巴菲特的第二个”</td></tr></tbody></table><h3 id="关键区别" tabindex="-1">关键区别 <a class="header-anchor" href="#关键区别" aria-label="Permalink to &quot;关键区别&quot;">​</a></h3><ul><li>阿吉特·贾恩被巴菲特看作最佳保险经理人之一</li><li>弗格森森则因为收购后的整合问题而受到赎楼</li><li>两者在保险领域的价值观和经营策略存在明显差异</li></ul><h2 id="历年式信" tabindex="-1">历年式信 <a class="header-anchor" href="#历年式信" aria-label="Permalink to &quot;历年式信&quot;">​</a></h2><p>1998, 2000, 2001, 2002, 2003</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/search.html?q=通用再保险">通用再保险</a> - 弗格森长期担任的公司</li><li><a href="/search.html?q=伯克尔希哈佩威">伯克尔希哈佩威</a> - 收购方</li><li><a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> - 评论发生变化的核心人物</li><li><a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a> - 同样是保险领域的重要人物</li></ul><hr><p><em>最后更新：2026-04-12</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=ron_ferguson在2013年股东信中的原话">2013年：完整翻译|/01_letters/2013年/翻译</a></li><li><a href="/search.html?q=ron_ferguson在1988年股东信中的原话">1988年：完整翻译|/01_letters/1988年/翻译</a></li><li><a href="/search.html?q=ron_ferguson在2011年股东信中的原话">2011年：完整翻译|/01_letters/2011年/翻译</a></li><li><a href="/search.html?q=ron_ferguson在1984年股东信中的原话">1984年：完整翻译|/01_letters/1984年/翻译</a></li><li><a href="/search.html?q=ron_ferguson在2004年股东信中的原话">2004年：完整翻译|/01_letters/2004年/翻译</a></li></ul>',34)])])}const q=t(h,[["render",d]]);export{f as __pageData,q as default};
